import java.io.*;
import java.util.*;

public class UtkarshVariant4 {
    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        String[] parts = in.readLine().split(" ");
        int n = Integer.parseInt(parts[0]);
        long k = Long.parseLong(parts[1]);

        long mod = 998244353L;
        if (k >= n) {
            out.println(0);
            out.flush();
            return;
        }

        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (fact[i - 1] * i) % mod;
        }
        invFact[n] = modPow(fact[n], mod - 2);
        for (int i = n - 1; i >= 1; i--) {
            invFact[i] = ((i + 1) * invFact[i + 1]) % mod;
        }

        if (k == 0) {
            out.println(fact[n]);
            out.flush();
            return;
        }

        int r = n - (int) k;
        long total = 0;
        int sign = 1;
        for (int i = 0; i < r; i++) {
            long comb = nCr(r, i, fact, invFact);
            long val = powMod(r - i, n);
            total = (total + sign * comb * val) % mod;
            sign *= -1;
        }
        long res = (2 * nCr(n, r, fact, invFact) * total) % mod;
        out.println(res);
        out.flush();
    }

    static long nCr(int n, int r, long[] fact, long[] invFact) {
        return fact[n] * invFact[r] % mod * invFact[n - r] % mod;
    }

    static long powMod(long base, int exp) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}
